describe('Inline Editing on Table Row', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('table').should('be.visible');
  });

  it('should enable inline editing when clicking on a table cell', () => {
    cy.get('table tbody tr').first().within(() => {
      cy.get('td').eq(1).click();
      cy.get('input[type="text"]').should('be.visible');
    });
  });

  it('should save changes when pressing Enter key', () => {
    const newValue = 'Updated Value';
    cy.get('table tbody tr').first().within(() => {
      cy.get('td').eq(1).click();
      cy.get('input[type="text"]')
        .clear()
        .type(newValue)
        .type('{enter}');
      cy.get('input[type="text"]').should('not.exist');
      cy.get('td').eq(1).should('contain', newValue);
    });
  });

  it('should cancel editing when pressing Escape key', () => {
    const originalValue = 'Original Value';
    cy.get('table tbody tr').first().within(() => {
      cy.get('td').eq(1).then(($cell) => {
        const initialText = $cell.text();
        cy.wrap($cell).click();
        cy.get('input[type="text"]')
          .clear()
          .type('New Value')
          .type('{esc}');
        cy.get('input[type="text"]').should('not.exist');
        cy.get('td').eq(1).should('contain', initialText);
      });
    });
  });

  it('should save changes when clicking outside the input field', () => {
    const newValue = 'Clicked Outside';
    cy.get('table tbody tr').first().within(() => {
      cy.get('td').eq(1).click();
      cy.get('input[type="text"]')
        .clear()
        .type(newValue);
    });
    cy.get('table tbody tr').eq(1).click();
    cy.get('table tbody tr').first().within(() => {
      cy.get('td').eq(1).should('contain', newValue);
      cy.get('input[type="text"]').should('not.exist');
    });
  });

  it('should handle empty input validation', () => {
    cy.get('table tbody tr').first().within(() => {
      cy.get('td').eq(1).click();
      cy.get('input[type="text"]')
        .clear()
        .type('{enter}');
      cy.get('input[type="text"]').should('be.visible');
      cy.get('.error-message').should('contain', 'Field cannot be empty');
    });
  });

  it('should allow editing multiple cells in sequence', () => {
    const firstValue = 'First Edit';
    const secondValue = 'Second Edit';

    cy.get('table tbody tr').first().within(() => {
      cy.get('td').eq(1).click();
      cy.get('input[type="text"]')
        .clear()
        .type(firstValue)
        .type('{enter}');
      cy.get('td').eq(1).should('contain', firstValue);

      cy.get('td').eq(2).click();
      cy.get('input[type="text"]')
        .clear()
        .type(secondValue)
        .type('{enter}');
      cy.get('td').eq(2).should('contain', secondValue);
    });
  });

  it('should not allow editing on read-only cells', () => {
    cy.get('table tbody tr').first().within(() => {
      cy.get('td[data-readonly="true"]').eq(0).click();
      cy.get('input[type="text"]').should('not.exist');
      cy.get('td[data-readonly="true"]').eq(0).should('not.have.class', 'editing');
    });
  });

  it('should persist changes after page refresh', () => {
    const newValue = 'Persistent Value';
    cy.get('table tbody tr').first().within(() => {
      cy.get('td').eq(1).click();
      cy.get('input[type="text"]')
        .clear()
        .type(newValue)
        .type('{enter}');
    });
    cy.reload();
    cy.get('table tbody tr').first().within(() => {
      cy.get('td').eq(1).should('contain', newValue);
    });
  });
});
